## メソッド 2：**Files APIで全メンバーのコンテンツを一括で取得**

Discordの[Files API](https://discord.com/developers/docs/resources/file#list-all-files-in-a-guild-or-channel)を利用すると、**指定のGuild/Channelの全てのファイル情報を取得できます**。

### 例：Node.js（discord.js）

```js
const { Client, GatewayIntentBits, Route } = require('discord.js');
const fetch = require('node-fetch');

const client = new Client({
  intents: [GatewayIntentBits.Guilds, GatewayIntentBits.MessageContent]
});

// グループID・チャンネルIDを設定
const GUILD_ID = 123456789012345678;
const CHANNEL_ID = 987654321098765432;

client.addRoute(new Route(Route.GuildFiles, { guilds: [GUILD_ID] }));

client.on('ready', () => console.log('Ready!'));

client.on('filesEvent', async filesEvent => {
  // ファイル一覧取得
  const allFiles = [];
  for (const file of filesEvent.files) {
    allFiles.push({
      id: file.id,
      name: file.name,
      url: file.url,
      channel: file.channel.id,
      guild: file.guild.id,
      type: file.type,
      created_at: file.created_at.toISOString()
    });
  }

  // ここから全ての画像URLを抽出しダウンロード
  const imageUrls = allFiles.filter(f => f.type === 'IMAGE').map(f => f.url);
  downloadAll(imageUrls);
});

function downloadAll(urls) {
